// Generated by Copilot — patched to handle >1000 rows via automatic pagination.
//
// Former Students / Student Cleanup (supabase/migrations/20261008): students
// carry a status ('active' | 'former'). Every reader in this module is
// status-aware and DEFAULTS TO ACTIVE STUDENTS ONLY, because these are the
// functions behind the current rosters, teacher class lists, attendance, marks
// entry, dashboards and the parent portal.
//
// Two rules make that safe:
//   1. A missing status (rows written before the migration, or a database that
//      has not been migrated yet) is treated as 'active' — nobody disappears.
//   2. The explicit column list would fail against an un-migrated database, so
//      every read retries once with the legacy column list. The feature then
//      degrades to "no former-student filtering" instead of breaking rosters.
// Callers that legitimately need leavers (historical reports, identity matching
// in the class import, duplicate merging, the family-ID screen) pass 'all'.

import { Student, StudentStatusFilter } from '../../types';
import { supabase } from '../supabase';

const MAX_QUERY_LIMIT = 10_000;
const PAGE_SIZE = 1000;

/** Columns every student read returns (status columns are appended when available). */
const STUDENT_COLUMNS = 'id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId';
/** Same list without createdAt — used by the class/roster readers that never needed it. */
const STUDENT_COLUMNS_NO_CREATED = 'id,name,className,parentId,govId,transport,parentPhone,familyId';
const STATUS_COLUMNS = 'status,statusUpdatedAt,statusUpdatedBy';

/** Flipped to false the first time the database reports a missing status column. */
let statusColumnsAvailable = true;

function studentColumns(base: string = STUDENT_COLUMNS): string {
  return statusColumnsAvailable ? `${base},${STATUS_COLUMNS}` : base;
}

function isMissingStatusColumnError(err: unknown): boolean {
  const e = (err ?? {}) as { code?: string | number; message?: string };
  const code = String(e.code ?? '');
  const message = String(e.message ?? '').toLowerCase();
  return (
    code === '42703' || code === 'PGRST204' ||
    message.includes("column students.status does not exist") ||
    message.includes("could not find the 'status' column") ||
    message.includes("could not find the 'students.status' column")
  );
}

/** Run a student read, retrying once without the status columns if needed. */
async function withStatusFallback<T>(
  run: (columns: string) => Promise<T>,
  base: string = STUDENT_COLUMNS,
): Promise<T> {
  try {
    return await run(studentColumns(base));
  } catch (err) {
    if (statusColumnsAvailable && isMissingStatusColumnError(err)) {
      statusColumnsAvailable = false;
      console.warn(
        '[students] students.status is not available (migration 20261008_former_students_cleanup.sql ' +
        'not applied yet) — continuing with the legacy column list. Former Students are NOT filtered ' +
        'out until the migration runs.',
      );
      return run(base);
    }
    throw err;
  }
}

/** A student with no status value is an active student (pre-migration rows). */
export function isActiveStudentRecord(student: Pick<Student, 'status'> | null | undefined): boolean {
  const status = student?.status;
  return status === undefined || status === null || status === 'active';
}

/** The one place the active/former decision is made on the client. */
export function filterStudentsByStatus<T extends Pick<Student, 'status'>>(
  rows: T[],
  filter: StudentStatusFilter = 'active',
): T[] {
  if (!Array.isArray(rows) || filter === 'all') return rows ?? [];
  if (filter === 'former') return rows.filter(row => row.status === 'former');
  return rows.filter(isActiveStudentRecord);
}

/**
 * Fetch all rows for a query that may exceed PostgREST's default 1000-row
 * limit. The caller provides a function that builds a fresh query (with any
 * filters) given a from/to range. Results are accumulated until a page
 * returns fewer rows than requested or the effective limit is reached.
 */
async function fetchAllPaginated<T>(
  buildQuery: (from: number, to: number) => any,
  effectiveLimit: number,
): Promise<T[]> {
  const all: T[] = [];
  let from = 0;
  while (true) {
    const remaining = effectiveLimit - all.length;
    if (remaining <= 0) break;
    const pageSize = Math.min(PAGE_SIZE, remaining);
    const to = from + pageSize - 1;
    const query = buildQuery(from, to);
    const { data, error } = await query;
    if (error) throw error;
    const rows = (data || []) as T[];
    all.push(...rows);
    if (rows.length < pageSize) break;
    from += pageSize;
  }
  return all;
}

function applyLimit(query: any, limit: number) {
  if (typeof query.limit === 'function') {
    return query.limit(Math.min(limit, MAX_QUERY_LIMIT));
  }
  return query;
}

/** All active students (pass 'all' for identity matching / historical views). */
export async function getStudents(
  limit: number = MAX_QUERY_LIMIT,
  status: StudentStatusFilter = 'active',
): Promise<Student[]> {
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  const rows = await withStatusFallback<Student[]>(columns =>
    fetchAllPaginated<Student>(
      (from, to) =>
        supabase
          .from('students')
          .select(columns)
          .order('id', { ascending: true })
          .range(from, to),
      effectiveLimit,
    ));
  return filterStudentsByStatus(rows, status);
}

export async function getStudentsPaginated(
  page: number = 1,
  limit: number = 50,
  search?: string,
  status: StudentStatusFilter = 'active',
): Promise<{ students: Student[]; total: number }> {
  const from = (page - 1) * limit;
  const to = from + limit - 1;

  const run = async (activeOnly: boolean) => {
    let query = supabase
      .from('students')
      .select('*', { count: 'exact' });

    if (search && search.trim()) {
      query = query.ilike('name', `%${search}%`);
    }
    // Server-side so the reported total matches the page (former students are
    // not silently counted).
    if (activeOnly && status !== 'all') {
      query = query.eq('status', status);
    }
    return query.range(from, to);
  };

  let result: any = await run(statusColumnsAvailable);
  if (result.error && statusColumnsAvailable && isMissingStatusColumnError(result.error)) {
    statusColumnsAvailable = false;
    console.warn('[students] students.status is not available — falling back to an unfiltered student page.');
    result = await run(false);
  }
  if (result.error) throw result.error;

  const rows = (result.data || []) as Student[];
  // Defence in depth: if the filter could not be pushed down, drop the rows
  // client-side so an active-only list never shows a leaver.
  const students = statusColumnsAvailable ? rows : filterStudentsByStatus(rows, status);
  return { students, total: result.count || 0 };
}

/** Single lookup by System ID: never filtered, so historical profiles resolve. */
export async function getStudentById(id: string): Promise<Student | undefined> {
  return withStatusFallback<Student | undefined>(async columns => {
    const { data, error } = await supabase
      .from('students')
      .select(columns)
      .eq('id', id)
      .single();
    if (error) return undefined;
    return data as unknown as Student | undefined;
  });
}

/** Current children of a parent ('all' keeps leavers reachable for history). */
export async function getStudentsByParent(
  parentId: string,
  status: StudentStatusFilter = 'active',
): Promise<Student[]> {
  const effectiveLimit = MAX_QUERY_LIMIT;
  const rows = await withStatusFallback<Student[]>(columns =>
    fetchAllPaginated<Student>(
      (from, to) =>
        supabase
          .from('students')
          .select(columns)
          .eq('parentId', parentId)
          .order('id', { ascending: true })
          .range(from, to),
      effectiveLimit,
    ));
  return filterStudentsByStatus(rows, status);
}

/** Current roster of a class. */
export async function getStudentsByClass(
  className: string,
  limit: number = 100,
  status: StudentStatusFilter = 'active',
): Promise<Student[]> {
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  // For small limits (UI lists) a single range query is enough, but we still
  // paginate when the requested limit exceeds PAGE_SIZE so a class with >1000
  // students is not silently truncated.
  const rows = await withStatusFallback<Student[]>(columns => {
    if (effectiveLimit <= PAGE_SIZE) {
      return Promise.resolve(
        supabase
          .from('students')
          .select(columns)
          .eq('className', className)
          .order('id', { ascending: true })
          .range(0, effectiveLimit - 1)
      ).then((res: any) => {
        if (res.error) throw res.error;
        return (res.data || []) as Student[];
      });
    }
    return fetchAllPaginated<Student>(
      (from, to) =>
        supabase
          .from('students')
          .select(columns)
          .eq('className', className)
          .order('id', { ascending: true })
          .range(from, to),
      effectiveLimit,
    );
  });
  return filterStudentsByStatus(rows, status);
}

export async function getStudentsByIds(
  ids: string[],
  limit: number = MAX_QUERY_LIMIT,
  status: StudentStatusFilter = 'all',
): Promise<Student[]> {
  if (!Array.isArray(ids) || ids.length === 0) return [];
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  // Supabase .in() with thousands of values can hit URL length limits; chunk
  // the ids and fetch each chunk with pagination.
  const uniqueIds = Array.from(new Set(ids));
  const chunks: string[][] = [];
  for (let i = 0; i < uniqueIds.length; i += PAGE_SIZE) {
    chunks.push(uniqueIds.slice(i, i + PAGE_SIZE));
  }
  const all: Student[] = [];
  for (const chunk of chunks) {
    if (all.length >= effectiveLimit) break;
    const remaining = effectiveLimit - all.length;
    // Each chunk is at most PAGE_SIZE, so a single range query suffices, but
    // we still paginate defensively.
    const fetched = await withStatusFallback<Student[]>(columns =>
      fetchAllPaginated<Student>(
        (from, to) =>
          supabase
            .from('students')
            .select(columns)
            .in('id', chunk)
            .order('id', { ascending: true })
            .range(from, to),
        Math.min(remaining, chunk.length),
      ));
    all.push(...fetched);
  }
  // Deduplicate by id in case of overlapping chunks (should not happen).
  const seen = new Set<string>();
  const deduped: Student[] = [];
  for (const s of all) {
    if (!seen.has(s.id)) {
      seen.add(s.id);
      deduped.push(s);
    }
  }
  return filterStudentsByStatus(deduped.slice(0, effectiveLimit), status);
}

/** Roster of several classes (teacher lists, dashboards). */
export async function getStudentsByClasses(
  classnames: string[],
  search?: string,
  limit: number = MAX_QUERY_LIMIT,
  status: StudentStatusFilter = 'active',
): Promise<Student[]> {
  // Default was historically 1000, which accidentally truncated rosters with
  // >1000 students. We now treat the limit as a maximum but fetch all pages
  // up to that maximum, so a request for 1000 still returns up to 1000, but
  // a request for 10_000 correctly returns up to 10_000 via pagination.
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  const rows = await withStatusFallback<Student[]>(columns => {
    if (effectiveLimit <= PAGE_SIZE) {
      // Fast path for small limits — single query.
      let query = supabase
        .from('students')
        .select(columns)
        .order('id', { ascending: true });
      if (classnames && classnames.length > 0) {
        query = query.in('className', classnames);
      }
      if (search && search.trim()) {
        query = query.ilike('name', `%${search}%`);
      }
      return Promise.resolve(query.range(0, effectiveLimit - 1)).then((res: any) => {
        if (res.error) throw res.error;
        return (res.data || []) as Student[];
      });
    }
    return fetchAllPaginated<Student>(
      (from, to) => {
        let q: any = supabase.from('students').select(columns);
        if (classnames && classnames.length > 0) {
          q = q.in('className', classnames);
        }
        if (search && search.trim()) {
          q = q.ilike('name', `%${search}%`);
        }
        return q.order('id', { ascending: true }).range(from, to);
      },
      effectiveLimit,
    );
  }, STUDENT_COLUMNS_NO_CREATED);
  return filterStudentsByStatus(rows, status);
}

export async function getStudentIdsByClasses(
  classnames: string[],
  status: StudentStatusFilter = 'active',
): Promise<string[]> {
  if (!classnames || classnames.length === 0) return [];
  const students = await getStudentsByClasses(classnames, undefined, MAX_QUERY_LIMIT, status);
  return students.map(student => student.id);
}

/** Distinct class names of currently enrolled students ('all' includes leavers). */
export async function getStudentClasses(status: StudentStatusFilter = 'active'): Promise<string[]> {
  const effectiveLimit = MAX_QUERY_LIMIT;
  const rows = await withStatusFallback<Array<{ className?: string } & Pick<Student, 'status'>>>(
    columns => fetchAllPaginated(
      (from, to) =>
        supabase.from('students').select(columns).order('className', { ascending: true }).range(from, to),
      effectiveLimit,
    ),
    'className',
  );
  const wanted = filterStudentsByStatus(rows, status);
  const classes = Array.from(new Set(wanted.map(r => r.className).filter(Boolean)));
  classes.sort();
  return classes as string[];
}

/**
 * Student mutations go through admin-gated SECURITY DEFINER RPCs. There is no
 * client INSERT/UPDATE/DELETE policy on `students` (RLS is SELECT-only); these
 * wrappers preserve the previous call signatures while enforcing the server
 * role check, audit trail, and enrollment-history maintenance.
 */
export async function createStudent(data: Omit<Student, 'id' | 'createdAt'>): Promise<Student> {
  const { data: created, error } = await supabase.rpc('create_student', {
    p_name: data.name,
    p_class: data.className,
    p_parent_id: data.parentId ?? null,
    p_gov_id: data.govId ?? null,
    p_parent_phone: data.parentPhone ?? null,
  });
  if (error) {
    console.error('Error creating student:', error);
    throw new Error(error.message);
  }
  return {
    id: (created as any)?.id,
    name: (created as any)?.name ?? data.name,
    className: (created as any)?.className ?? data.className,
    parentId: data.parentId ?? null,
    govId: data.govId ?? null,
    parentPhone: data.parentPhone ?? null,
    createdAt: new Date().toISOString(),
  } as Student;
}

/**
 * update_student() (20260906c_student_write_security.sql) uses NULL as the
 * "leave this column alone" sentinel for every optional argument, and applies
 * NULLIF(p_parent_id,'') when it does write. So:
 *   * omit the key entirely            -> NULL  -> column untouched
 *   * pass a parent id                 -> that id is assigned
 *   * pass null (explicit unassign)    -> '' -> the RPC stores NULL
 * Sending raw null for an explicit unassign (the previous behaviour) was
 * silently a no-op: administrators could never REMOVE a wrongly assigned
 * parent from a student.
 */
function rpcNullable(value: string | null | undefined): string | null {
  if (value === undefined) return null; // no change
  return value ?? '';                   // '' => explicit clear inside the RPC
}

export async function updateStudent(id: string, data: Partial<Student>): Promise<Student | null> {
  const { error } = await supabase.rpc('update_student', {
    p_student_id: id,
    p_name: data.name ?? null,
    p_class: data.className ?? null,
    p_parent_id: rpcNullable(data.parentId),
    p_gov_id: rpcNullable(data.govId),
    p_parent_phone: rpcNullable(data.parentPhone),
    p_transport: rpcNullable(data.transport),
  });
  if (error) {
    console.error('Error updating student:', error);
    throw new Error(error.message);
  }
  return (await getStudentById(id)) ?? null;
}

/** Narrow office/admin action: change only the parent link (active or former student). */
export async function assignStudentParent(id: string, parentId: string | null): Promise<void> {
  const { error } = await supabase.rpc('assign_student_parent', {
    p_student_id: id,
    p_parent_id: parentId ?? '',
  });
  if (error) throw new Error(error.message || 'Failed to assign parent');
}

export async function deleteStudent(id: string): Promise<boolean> {
  const { error } = await supabase.rpc('delete_student', { p_student_id: id });
  if (error) {
    console.error('Error deleting student:', error);
    return false;
  }
  // Grades/attendance/homework cascade via FK ON DELETE inside the transaction.
  return true;
}

export async function promoteStudentsByClass(
  fromClass: string,
  toClass: string,
  academicYearId?: string
): Promise<number> {
  const { data, error } = await supabase.rpc('promote_students', {
    from_class: fromClass,
    to_class: toClass,
    academic_year_id: academicYearId ?? null,
  });
  if (error) throw new Error(error.message);
  return Array.isArray(data) ? data.length : 0;
}
